/**
 * Re-encode the product catalogue images to WebP at display resolution.
 *
 * The catalogue was committed as 1024x1024 originals, 102 of them lossless PNG
 * encodings of photographs at ~3 MB each, while the app renders them at 350px
 * (grids) and 550px (product detail). This converts them in place to WebP at
 * `--max-dimension` on the long edge and rewrites the data files that point at
 * them.
 *
 * Scope is whatever the catalogue data references, which deliberately leaves
 * out `hero.png`, `contact-bg.jpg` and `about/mission.png`: those are full-bleed
 * backgrounds reached from CSS, they render far wider than a product thumbnail,
 * and all three together are 3 MB. `tests/scripts/test_image_encoding.py`
 * carries the same split and fails if anything else grows back.
 *
 * Idempotent: references already pointing at an existing WebP are left alone,
 * so a re-run after new images land converts only the new ones.
 *
 *   node scripts/reencode-catalogue-images.mjs [--dry-run] [--quality 82]
 *                                              [--max-dimension 600]
 */
import fs from "fs/promises";
import path from "path";
import { fileURLToPath } from "url";
import sharp from "sharp";

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const PUBLIC_DIR = path.join(REPO_ROOT, "apps/web/public");
const DATA_FILES = ["products.json", "categories.json", "brands.json"];

const SOURCE_SUFFIXES = new Set([".jpg", ".jpeg", ".png"]);
const IMAGE_REF = /\/images\/[A-Za-z0-9_./-]+\.(?:jpg|jpeg|png|webp)/gi;

function parseArgs(argv) {
  const options = { dryRun: false, quality: 82, maxDimension: 600 };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--dry-run") {
      options.dryRun = true;
    } else if (arg === "--quality") {
      options.quality = Number(argv[(i += 1)]);
    } else if (arg === "--max-dimension") {
      options.maxDimension = Number(argv[(i += 1)]);
    } else {
      throw new Error(`unknown argument: ${arg}`);
    }
  }
  if (!Number.isInteger(options.quality) || options.quality < 1 || options.quality > 100) {
    throw new Error("--quality must be an integer between 1 and 100");
  }
  if (!Number.isInteger(options.maxDimension) || options.maxDimension < 1) {
    throw new Error("--max-dimension must be a positive integer");
  }
  return options;
}

const toAbsolute = (ref) => path.join(PUBLIC_DIR, ref.replace(/^\//, ""));
const toWebpRef = (ref) => `${ref.slice(0, ref.length - path.extname(ref).length)}.webp`;

async function readDataFiles() {
  return Promise.all(
    DATA_FILES.map(async (name) => ({
      name,
      absolutePath: path.join(PUBLIC_DIR, name),
      text: await fs.readFile(path.join(PUBLIC_DIR, name), "utf8"),
    }))
  );
}

async function fileSize(absolutePath) {
  const stat = await fs.stat(absolutePath);
  return stat.size;
}

async function exists(absolutePath) {
  try {
    await fs.access(absolutePath);
    return true;
  } catch {
    return false;
  }
}

/**
 * Every distinct catalogue reference still pointing at a JPEG or PNG.
 *
 * Reads the references rather than walking the directory so a file the data
 * stopped pointing at is left for the orphan check in
 * `tests/scripts/test_image_references.py` to report, instead of being silently
 * re-encoded and kept alive.
 */
function collectSourceRefs(dataFiles) {
  const refs = new Set();
  for (const file of dataFiles) {
    for (const match of file.text.matchAll(IMAGE_REF)) {
      const ref = match[0];
      if (SOURCE_SUFFIXES.has(path.extname(ref).toLowerCase())) {
        refs.add(ref);
      }
    }
  }
  return [...refs].sort();
}

async function convert(ref, options) {
  const source = toAbsolute(ref);
  const target = toAbsolute(toWebpRef(ref));
  const before = await fileSize(source);

  const buffer = await sharp(source)
    .resize(options.maxDimension, options.maxDimension, {
      fit: "inside",
      withoutEnlargement: true,
    })
    .webp({ quality: options.quality })
    .toBuffer();

  if (!options.dryRun) {
    await fs.writeFile(target, buffer);
    await fs.rm(source);
  }
  return { before, after: buffer.length };
}

async function run() {
  const options = parseArgs(process.argv.slice(2));
  const dataFiles = await readDataFiles();
  const refs = collectSourceRefs(dataFiles);

  const missing = [];
  for (const ref of refs) {
    if (!(await exists(toAbsolute(ref)))) {
      missing.push(ref);
    }
  }
  if (missing.length > 0) {
    throw new Error(
      `catalogue references ${missing.length} file(s) that do not exist, ` +
        `starting with ${missing[0]}`
    );
  }

  let before = 0;
  let after = 0;
  let largest = 0;
  for (const [index, ref] of refs.entries()) {
    const result = await convert(ref, options);
    before += result.before;
    after += result.after;
    largest = Math.max(largest, result.after);
    if ((index + 1) % 100 === 0) {
      process.stdout.write(`  ${index + 1}/${refs.length}\n`);
    }
  }

  if (!options.dryRun) {
    for (const file of dataFiles) {
      const rewritten = file.text.replace(IMAGE_REF, (ref) =>
        SOURCE_SUFFIXES.has(path.extname(ref).toLowerCase()) ? toWebpRef(ref) : ref
      );
      if (rewritten !== file.text) {
        await fs.writeFile(file.absolutePath, rewritten);
      }
    }
  }

  const mib = (bytes) => `${(bytes / 1024 ** 2).toFixed(1)} MiB`;
  const saved = before === 0 ? 0 : Math.round((1 - after / before) * 100);
  console.log(
    `${options.dryRun ? "[dry run] " : ""}re-encoded ${refs.length} image(s) at ` +
      `q${options.quality}/${options.maxDimension}px: ${mib(before)} -> ${mib(after)} ` +
      `(${saved}% smaller, largest ${(largest / 1024).toFixed(0)} KiB)`
  );
}

run().catch((error) => {
  console.error(error.message);
  process.exit(1);
});

/**
 * Measure the q82/600px re-encode against the originals at the sizes the app
 * actually renders (350px grid, 550px detail), and dump the worst cases.
 *
 * Nothing here is committed: it produces the evidence for the review.
 */
import fs from "fs/promises";
import path from "path";
import sharp from "sharp";

const REPO_ROOT = "/home/scottdensmore/Developer/scottdensmore/contoso";
const PUBLIC_DIR = path.join(REPO_ROOT, "apps/web/public");
const OUT = path.dirname(new URL(import.meta.url).pathname);

const QUALITY = 82;
const MAX_DIM = 600;
const RENDER_SIZES = [550, 350];

const IMAGE_REF = /\/images\/[A-Za-z0-9_./-]+\.(?:jpg|jpeg|png|webp)/gi;

async function catalogueRefs() {
  const refs = new Set();
  for (const name of ["products.json", "categories.json", "brands.json"]) {
    const text = await fs.readFile(path.join(PUBLIC_DIR, name), "utf8");
    for (const m of text.matchAll(IMAGE_REF)) refs.add(m[0]);
  }
  return [...refs].sort();
}

/** Mean SSIM on the luma plane, 8x8 uniform windows, stride 4. */
function ssim(a, b, size) {
  const C1 = (0.01 * 255) ** 2;
  const C2 = (0.03 * 255) ** 2;
  const win = 8;
  const stride = 4;
  let total = 0;
  let n = 0;
  for (let y = 0; y + win <= size; y += stride) {
    for (let x = 0; x + win <= size; x += stride) {
      let sa = 0, sb = 0, saa = 0, sbb = 0, sab = 0;
      for (let j = 0; j < win; j += 1) {
        for (let i = 0; i < win; i += 1) {
          const idx = (y + j) * size + (x + i);
          const va = a[idx];
          const vb = b[idx];
          sa += va; sb += vb; saa += va * va; sbb += vb * vb; sab += va * vb;
        }
      }
      const c = win * win;
      const ma = sa / c;
      const mb = sb / c;
      const va = saa / c - ma * ma;
      const vb = sbb / c - mb * mb;
      const cov = sab / c - ma * mb;
      total +=
        ((2 * ma * mb + C1) * (2 * cov + C2)) /
        ((ma * ma + mb * mb + C1) * (va + vb + C2));
      n += 1;
    }
  }
  return total / n;
}

const renderTo = (buf, size) =>
  sharp(buf).resize(size, size, { fit: "inside" });

const luma = (buf, size) =>
  renderTo(buf, size).greyscale().raw().toBuffer();

async function main() {
  const refs = await catalogueRefs();
  const rows = [];
  let beforeBytes = 0;
  let afterBytes = 0;
  let largest = 0;

  for (const [index, ref] of refs.entries()) {
    const source = path.join(PUBLIC_DIR, ref.replace(/^\//, ""));
    const original = await fs.readFile(source);
    const meta = await sharp(original).metadata();
    const encoded = await sharp(original)
      .resize(MAX_DIM, MAX_DIM, { fit: "inside", withoutEnlargement: true })
      .webp({ quality: QUALITY })
      .toBuffer();

    beforeBytes += original.length;
    afterBytes += encoded.length;
    largest = Math.max(largest, encoded.length);

    const scores = {};
    for (const size of RENDER_SIZES) {
      const [a, b] = await Promise.all([luma(original, size), luma(encoded, size)]);
      scores[size] = ssim(a, b, size);
    }

    rows.push({
      ref,
      format: meta.format,
      before: original.length,
      after: encoded.length,
      ssim550: scores[550],
      ssim350: scores[350],
    });

    if ((index + 1) % 100 === 0) process.stdout.write(`  ${index + 1}/${refs.length}\n`);
  }

  await fs.writeFile(
    path.join(OUT, "measurements.json"),
    JSON.stringify({ quality: QUALITY, maxDim: MAX_DIM, beforeBytes, afterBytes, largest, rows }, null, 2)
  );

  const mib = (b) => (b / 1024 ** 2).toFixed(1);
  const sorted = [...rows].sort((x, y) => x.ssim550 - y.ssim550);
  console.log(`${refs.length} images: ${mib(beforeBytes)} MiB -> ${mib(afterBytes)} MiB`);
  console.log(`largest output ${(largest / 1024).toFixed(0)} KiB`);
  const stat = (k) => {
    const v = rows.map((r) => r[k]).sort((a, b) => a - b);
    const q = (p) => v[Math.floor(p * (v.length - 1))];
    return `min ${q(0).toFixed(4)} p05 ${q(0.05).toFixed(4)} median ${q(0.5).toFixed(4)} max ${q(1).toFixed(4)}`;
  };
  console.log(`ssim@550 ${stat("ssim550")}`);
  console.log(`ssim@350 ${stat("ssim350")}`);
  console.log("\nworst 12 at 550:");
  for (const r of sorted.slice(0, 12)) {
    console.log(`  ${r.ssim550.toFixed(4)}  ${r.ssim350.toFixed(4)}  ${r.format}  ${(r.before / 1024).toFixed(0)}K -> ${(r.after / 1024).toFixed(0)}K  ${r.ref}`);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

