/** Render before/after tiles at the app's display sizes, lossless, as data URIs. */
import fs from "fs/promises";
import path from "path";
import sharp from "sharp";

const PUBLIC_DIR = "/home/scottdensmore/Developer/scottdensmore/contoso/apps/web/public";
const OUT = path.dirname(new URL(import.meta.url).pathname);

const SAMPLES = [
  { ref: "/images/products/hiking-clothing/102/main.jpg", note: "worst SSIM in the catalogue" },
  { ref: "/images/products/backpacks/76/detail.jpg", note: "worst case among the large files" },
  { ref: "/images/products/tents/26/main.jpg", note: "fine mesh and guy lines" },
  { ref: "/images/7/45e09e69-17c4-47d9-a501-2f8177e34349.png", note: "worst of the 3 MB PNGs" },
  { ref: "/images/17/b77e9f01-195b-4870-bc86-c4f988bc71e8.png", note: "typical PNG" },
  { ref: "/images/products/hiking-footwear/149/angle.jpg", note: "typical JPEG" },
];

const CROP = 300;

const dataUri = (buf) => `data:image/webp;base64,${buf.toString("base64")}`;
const render = (buf, size) =>
  sharp(buf).resize(size, size, { fit: "inside" }).webp({ lossless: true }).toBuffer();

/** A 1:1 slice of the 550px render, where q82 artefacts are actually visible. */
async function crop(buf) {
  const rendered = await sharp(buf).resize(550, 550, { fit: "inside" }).toBuffer();
  const meta = await sharp(rendered).metadata();
  return sharp(rendered)
    .extract({
      left: Math.max(0, Math.floor((meta.width - CROP) / 2)),
      top: Math.max(0, Math.floor((meta.height - CROP) / 2)),
      width: Math.min(CROP, meta.width),
      height: Math.min(CROP, meta.height),
    })
    .webp({ lossless: true })
    .toBuffer();
}

const out = [];
let bytes = 0;
for (const sample of SAMPLES) {
  const original = await fs.readFile(path.join(PUBLIC_DIR, sample.ref.replace(/^\//, "")));
  const encoded = await sharp(original)
    .resize(600, 600, { fit: "inside", withoutEnlargement: true })
    .webp({ quality: 82 })
    .toBuffer();

  const tiles = {};
  for (const [key, source] of [["before", original], ["after", encoded]]) {
    tiles[`${key}550`] = await render(source, 550);
    tiles[`${key}350`] = await render(source, 350);
    tiles[`${key}Crop`] = await crop(source);
  }
  for (const value of Object.values(tiles)) bytes += value.length;

  out.push({
    ...sample,
    beforeBytes: original.length,
    afterBytes: encoded.length,
    tiles: Object.fromEntries(Object.entries(tiles).map(([k, v]) => [k, dataUri(v)])),
  });
  console.log(sample.ref, (bytes / 1024 ** 2).toFixed(2), "MiB so far");
}

await fs.writeFile(path.join(OUT, "tiles.json"), JSON.stringify(out));
console.log("raw tile bytes", (bytes / 1024 ** 2).toFixed(2), "MiB");

/**
 * What the neighbouring settings would buy, so the q82/600 call is a comparison
 * rather than an assertion. Originals come from git, since the conversion has
 * already replaced them in the working tree.
 */
import { execFileSync } from "child_process";
import fs from "fs/promises";
import path from "path";
import sharp from "sharp";

const REPO = "/home/scottdensmore/Developer/scottdensmore/contoso";
const OUT = path.dirname(new URL(import.meta.url).pathname);
const measurements = JSON.parse(await fs.readFile(path.join(OUT, "measurements.json"), "utf8"));

const CONFIGS = [
  { label: "q82/600", quality: 82, maxDim: 600 },
  { label: "q88/600", quality: 88, maxDim: 600 },
  { label: "q82/800", quality: 82, maxDim: 800 },
  { label: "q90/800", quality: 90, maxDim: 800 },
  { label: "q75/600", quality: 75, maxDim: 600 },
];

// The 20 weakest plus a deterministic spread across the rest, so the size totals
// are not extrapolated from the hardest images alone.
const byScore = [...measurements.rows].sort((a, b) => a.ssim550 - b.ssim550);
const worst = byScore.slice(0, 20);
const spread = byScore.filter((_, i) => i >= 20 && i % 17 === 0);
const sample = [...worst, ...spread];

const C1 = (0.01 * 255) ** 2;
const C2 = (0.03 * 255) ** 2;
function ssim(a, b, size) {
  const win = 8, stride = 4;
  let total = 0, n = 0;
  for (let y = 0; y + win <= size; y += stride) {
    for (let x = 0; x + win <= size; x += stride) {
      let sa = 0, sb = 0, saa = 0, sbb = 0, sab = 0;
      for (let j = 0; j < win; j += 1) {
        for (let i = 0; i < win; i += 1) {
          const idx = (y + j) * size + (x + i);
          const va = a[idx], vb = b[idx];
          sa += va; sb += vb; saa += va * va; sbb += vb * vb; sab += va * vb;
        }
      }
      const c = win * win;
      const ma = sa / c, mb = sb / c;
      const va = saa / c - ma * ma, vb = sbb / c - mb * mb;
      const cov = sab / c - ma * mb;
      total += ((2 * ma * mb + C1) * (2 * cov + C2)) / ((ma * ma + mb * mb + C1) * (va + vb + C2));
      n += 1;
    }
  }
  return total / n;
}

const luma = (buf, size) =>
  sharp(buf).resize(size, size, { fit: "inside" }).greyscale().raw().toBuffer();

const results = {};
for (const config of CONFIGS) results[config.label] = { bytes: 0, scores: [], worstScores: [] };

for (const [index, row] of sample.entries()) {
  const original = execFileSync(
    "git",
    ["show", `HEAD:apps/web/public${row.ref}`],
    { cwd: REPO, maxBuffer: 64 * 1024 * 1024, encoding: "buffer" }
  );
  const reference = await luma(original, 550);

  for (const config of CONFIGS) {
    const encoded = await sharp(original)
      .resize(config.maxDim, config.maxDim, { fit: "inside", withoutEnlargement: true })
      .webp({ quality: config.quality })
      .toBuffer();
    const score = ssim(reference, await luma(encoded, 550), 550);
    results[config.label].bytes += encoded.length;
    results[config.label].scores.push(score);
    if (index < 20) results[config.label].worstScores.push(score);
  }
  if ((index + 1) % 10 === 0) process.stdout.write(`  ${index + 1}/${sample.length}\n`);
}

const mean = (v) => v.reduce((s, x) => s + x, 0) / v.length;
const q82Bytes = results["q82/600"].bytes;
console.log(`sample of ${sample.length} (20 weakest + ${spread.length} spread)`);
for (const config of CONFIGS) {
  const r = results[config.label];
  console.log(
    `${config.label.padEnd(8)} bytes ${(r.bytes / 1024 ** 2).toFixed(2)} MiB ` +
      `(${((r.bytes / q82Bytes) * 100).toFixed(0)}% of q82/600)  ` +
      `mean ssim ${mean(r.scores).toFixed(4)}  ` +
      `mean of 20 weakest ${mean(r.worstScores).toFixed(4)}  ` +
      `min ${Math.min(...r.scores).toFixed(4)}`
  );
}
await fs.writeFile(path.join(OUT, "alternatives.json"), JSON.stringify(results, null, 2));

