/**
 * Before/after tiles at the sizes the app renders, plus the 2x case.
 *
 * "Before" is the 1024px original from git; "after" is the committed q82/600
 * WebP. Both are resampled to the display size the way next/image and the
 * browser would, so the pair differs only by what the re-encode cost.
 *
 * Display tiles are lossless WebP: the artefacts under review must not be
 * re-encoded on their way to the page.
 */
import { execFileSync } from "child_process";
import fs from "fs/promises";
import path from "path";
import sharp from "sharp";

const REPO = "/home/scottdensmore/Developer/scottdensmore/contoso";
const PUBLIC_DIR = path.join(REPO, "apps/web/public");
const OUT = path.dirname(new URL(import.meta.url).pathname);

const SAMPLES = [
  { ref: "/images/products/hiking-clothing/102/main", from: "jpg", note: "weakest score in the catalogue" },
  { ref: "/images/products/backpacks/76/detail", from: "jpg", note: "weakest of the heavy files" },
  { ref: "/images/products/tents/26/main", from: "jpg", note: "fine mesh and guy lines" },
  { ref: "/images/7/45e09e69-17c4-47d9-a501-2f8177e34349", from: "png", note: "weakest of the 3 MB PNGs" },
  { ref: "/images/17/b77e9f01-195b-4870-bc86-c4f988bc71e8", from: "png", note: "typical PNG" },
  { ref: "/images/products/hiking-footwear/149/angle", from: "jpg", note: "typical JPEG" },
];

/** The detail page box is 550 CSS px, so a 2x screen asks for 1100 device px. */
const RETINA_DEVICE_WIDTH = 1100;
const RETINA_CROP = 440;

const dataUri = (buf) => `data:image/webp;base64,${buf.toString("base64")}`;
const lossless = (pipeline) => pipeline.webp({ lossless: true }).toBuffer();

const render = (buf, size) => lossless(sharp(buf).resize(size, size, { fit: "inside" }));

/** What a 2x display actually shows: the source scaled to 1100, cropped 1:1. */
async function retinaCrop(buf) {
  const scaled = await sharp(buf)
    .resize(RETINA_DEVICE_WIDTH, RETINA_DEVICE_WIDTH, { fit: "inside" })
    .toBuffer();
  const meta = await sharp(scaled).metadata();
  return lossless(
    sharp(scaled).extract({
      left: Math.floor((meta.width - RETINA_CROP) / 2),
      top: Math.floor((meta.height - RETINA_CROP) / 2),
      width: RETINA_CROP,
      height: RETINA_CROP,
    })
  );
}

const measurements = JSON.parse(await fs.readFile(path.join(OUT, "measurements.json"), "utf8"));
const scoreFor = (ref, from) =>
  measurements.rows.find((row) => row.ref === `${ref}.${from}`);

const out = [];
let bytes = 0;
for (const sample of SAMPLES) {
  const originalRef = `${sample.ref}.${sample.from}`;
  const original = execFileSync("git", ["show", `HEAD:apps/web/public${originalRef}`], {
    cwd: REPO,
    maxBuffer: 64 * 1024 * 1024,
    encoding: "buffer",
  });
  const encoded = await fs.readFile(path.join(PUBLIC_DIR, `${sample.ref}.webp`.replace(/^\//, "")));

  const tiles = {};
  for (const [key, source] of [["before", original], ["after", encoded]]) {
    tiles[`${key}550`] = await render(source, 550);
    tiles[`${key}350`] = await render(source, 350);
    tiles[`${key}Retina`] = await retinaCrop(source);
  }
  for (const value of Object.values(tiles)) bytes += value.length;

  const score = scoreFor(sample.ref, sample.from);
  out.push({
    ref: originalRef,
    note: sample.note,
    from: sample.from,
    beforeBytes: original.length,
    afterBytes: encoded.length,
    ssim550: score.ssim550,
    ssim350: score.ssim350,
    tiles: Object.fromEntries(Object.entries(tiles).map(([k, v]) => [k, dataUri(v)])),
  });
  console.log(originalRef, (bytes / 1024 ** 2).toFixed(2), "MiB");
}

await fs.writeFile(path.join(OUT, "tiles.json"), JSON.stringify(out));
console.log("raw tile bytes", (bytes / 1024 ** 2).toFixed(2), "MiB");

/** Assemble the review page from the measured data and the rendered tiles. */
import fs from "fs/promises";
import path from "path";

const OUT = path.dirname(new URL(import.meta.url).pathname);
const read = async (name) => JSON.parse(await fs.readFile(path.join(OUT, name), "utf8"));

const tiles = await read("tiles.json");
const measurements = await read("measurements.json");
const alternatives = await read("alternatives.json");
const fullsize = await read("fullsize.json");

const rows = measurements.rows;
const png = rows.filter((r) => r.format === "png");
const jpeg = rows.filter((r) => r.format === "jpeg");
const sum = (list, key) => list.reduce((total, row) => total + row[key], 0);
const mib = (bytes) => (bytes / 1024 ** 2).toFixed(1);
const kib = (bytes) => Math.round(bytes / 1024);
const pct = (before, after) => Math.round((1 - after / before) * 100);

const quantile = (values, p) => {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(p * (sorted.length - 1))];
};
const scores550 = rows.map((r) => r.ssim550);
const scores350 = rows.map((r) => r.ssim350);

const mean = (values) => values.reduce((s, v) => s + v, 0) / values.length;

// Sample byte totals scale to the catalogue by the ratio the sample itself
// shows against q82/600, whose full-catalogue total is known exactly.
const sampleQ82 = alternatives["q82/600"].bytes;
const catalogueAfter = sum(rows, "after");
const projected = (label) =>
  fullsize[label]
    ? fullsize[label].bytes
    : (alternatives[label].bytes / sampleQ82) * catalogueAfter;

const OPTIONS = [
  { label: "q75/600", note: "" },
  { label: "q82/600", note: "delivered" },
  { label: "q88/600", note: "" },
  { label: "q82/800", note: "" },
  { label: "q82/1100", note: "holds 2× on the detail page" },
  { label: "q88/1100", note: "" },
];

const optionRows = OPTIONS.map((option) => {
  const alt = alternatives[option.label];
  const bytes = projected(option.label);
  const density = (dim) => (Number(option.label.split("/")[1]) / 1100).toFixed(2);
  return {
    ...option,
    bytes,
    maxDim: Number(option.label.split("/")[1]),
    meanSsim: alt ? mean(alt.scores) : null,
    worstMean: alt ? mean(alt.worstScores) : null,
    min: alt ? Math.min(...alt.scores) : null,
    density: density(),
  };
});

const escape = (value) =>
  String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const plates = tiles
  .map(
    (tile, index) => `
      <figure class="plate" data-state="after">
        <figcaption class="plate-head">
          <div class="plate-id">
            <span class="eyebrow">Sample ${index + 1}</span>
            <code class="path">${escape(tile.ref)}</code>
            <p class="plate-note">${escape(tile.note)}</p>
          </div>
          <dl class="plate-stats">
            <div><dt>Source</dt><dd>${kib(tile.beforeBytes)} KiB</dd></div>
            <div><dt>WebP</dt><dd>${kib(tile.afterBytes)} KiB</dd></div>
            <div><dt>SSIM 550</dt><dd>${tile.ssim550.toFixed(4)}</dd></div>
            <div><dt>SSIM 350</dt><dd>${tile.ssim350.toFixed(4)}</dd></div>
          </dl>
          <div class="switch" role="group" aria-label="Compare ${escape(tile.ref)}">
            <button type="button" data-show="before">Before</button>
            <button type="button" data-show="after" aria-pressed="true">After</button>
          </div>
        </figcaption>

        <div class="card">
          <div class="viewport" style="--w: 550px">
            <span class="vp-label">Detail page &middot; 550&thinsp;&times;&thinsp;550</span>
            <div class="stack" style="--h: 550px">
              <img class="is-before" src="${tile.tiles.before550}" alt="${escape(tile.ref)} rendered at 550 pixels from the original" width="550" height="550">
              <img class="is-after" src="${tile.tiles.after550}" alt="${escape(tile.ref)} rendered at 550 pixels from the WebP" width="550" height="550">
            </div>
          </div>

          <div class="viewport" style="--w: 350px">
            <span class="vp-label">Home grid &middot; 350&thinsp;&times;&thinsp;350</span>
            <div class="stack" style="--h: 350px">
              <img class="is-before" src="${tile.tiles.before350}" alt="${escape(tile.ref)} rendered at 350 pixels from the original" width="350" height="350">
              <img class="is-after" src="${tile.tiles.after350}" alt="${escape(tile.ref)} rendered at 350 pixels from the WebP" width="350" height="350">
            </div>
          </div>

          <div class="viewport" style="--w: 440px">
            <span class="vp-label">2&times; screen &middot; 1:1 pixels, magnified</span>
            <div class="stack" style="--h: 440px">
              <img class="is-before" src="${tile.tiles.beforeRetina}" alt="${escape(tile.ref)} centre crop as a 2x display shows it, from the original" width="440" height="440">
              <img class="is-after" src="${tile.tiles.afterRetina}" alt="${escape(tile.ref)} centre crop as a 2x display shows it, from the WebP" width="440" height="440">
            </div>
          </div>
        </div>
      </figure>`
  )
  .join("\n");

const html = `<title>WebP re-encode: before and after at display size</title>
<style>
