<script>
  const plates = Array.from(document.querySelectorAll(".plate"));

  const setState = (plate, state) => {
    plate.dataset.state = state;
    plate.querySelectorAll(".switch button").forEach((button) => {
      button.setAttribute("aria-pressed", String(button.dataset.show === state));
    });
  };

  plates.forEach((plate) => {
    plate.querySelectorAll(".switch button").forEach((button) => {
      button.addEventListener("click", () => setState(plate, button.dataset.show));
    });
  });

  document.getElementById("all-before").addEventListener("click", () => {
    plates.forEach((plate) => setState(plate, "before"));
  });
  document.getElementById("all-after").addEventListener("click", () => {
    plates.forEach((plate) => setState(plate, "after"));
  });

  // Hold B to peek at the originals, then release. Restores whatever each
  // plate was showing rather than flattening them all to "after".
  let held = null;
  addEventListener("keydown", (event) => {
    if (event.key.toLowerCase() !== "b" || event.repeat || held) return;
    const target = event.target;
    if (target instanceof HTMLElement && target.closest("input, textarea")) return;
    held = plates.map((plate) => plate.dataset.state);
    plates.forEach((plate) => setState(plate, "before"));
  });
  addEventListener("keyup", (event) => {
    if (event.key.toLowerCase() !== "b" || !held) return;
    plates.forEach((plate, index) => setState(plate, held[index]));
    held = null;
  });
</script>
`;

