/**
 * Compare what the browser actually paints, not what is on disk.
 *
 * The app never serves these files directly. Every one goes through
 * `/_next/image?url=...&w=<width>&q=75`, so the pixels a visitor sees are a
 * q75 WebP re-encode at the width the layout asked for, from both the old
 * sources and the new ones. Measuring source-against-source, as the first pass
 * did, scores a file nobody downloads.
 *
 * The optimiser never upscales past its source, which is the whole of the 2x
 * story: a 550px box on a retina screen asks for 1100 device pixels, the old
 * 1024px originals answered with 1024, and a 600px source answers with 600.
 */
import { execFileSync } from "child_process";
import fs from "fs/promises";
import path from "path";
import sharp from "sharp";

const REPO = "/home/scottdensmore/Developer/scottdensmore/contoso";
const PUBLIC_DIR = path.join(REPO, "apps/web/public");
const OUT = path.dirname(new URL(import.meta.url).pathname);

const OPTIMISER_QUALITY = 75;

// box: the CSS box the layout gives the image. dpr: the screen. device: what
// the browser therefore asks the optimiser for, and the size it paints at.
const CASES = [
  { key: "detail1x", label: "Detail page, 1x", box: 550, dpr: 1, device: 550 },
  { key: "grid1x", label: "Home and category grid, 1x", box: 350, dpr: 1, device: 350 },
  { key: "detail2x", label: "Detail page, 2x", box: 550, dpr: 2, device: 1100, sampleOnly: true },
  { key: "grid2x", label: "Home and category grid, 2x", box: 350, dpr: 2, device: 700, sampleOnly: true },
];

const C1 = (0.01 * 255) ** 2;
const C2 = (0.03 * 255) ** 2;
function ssim(a, b, size) {
  const win = 8, stride = 4;
  let total = 0, n = 0;
  for (let y = 0; y + win <= size; y += stride) {
    for (let x = 0; x + win <= size; x += stride) {
      let sa = 0, sb = 0, saa = 0, sbb = 0, sab = 0;
      for (let j = 0; j < win; j += 1) {
        for (let i = 0; i < win; i += 1) {
          const idx = (y + j) * size + (x + i);
          const va = a[idx], vb = b[idx];
          sa += va; sb += vb; saa += va * va; sbb += vb * vb; sab += va * vb;
        }
      }
      const c = win * win;
      const ma = sa / c, mb = sb / c;
      const va = saa / c - ma * ma, vb = sbb / c - mb * mb;
      const cov = sab / c - ma * mb;
      total += ((2 * ma * mb + C1) * (2 * cov + C2)) / ((ma * ma + mb * mb + C1) * (va + vb + C2));
      n += 1;
    }
  }
  return total / n;
}

/** One trip through the Next image optimiser, capped at the source width. */
async function deliver(source, deviceWidth) {
  const meta = await sharp(source).metadata();
  const width = Math.min(deviceWidth, meta.width);
  return sharp(source)
    .resize(width, width, { fit: "inside", withoutEnlargement: true })
    .webp({ quality: OPTIMISER_QUALITY })
    .toBuffer();
}

/** The painted result: the delivered file scaled by the browser to fill the box. */
const painted = (delivered, deviceWidth) =>
  sharp(delivered).resize(deviceWidth, deviceWidth, { fit: "fill" });

const lumaOf = (delivered, deviceWidth) =>
  painted(delivered, deviceWidth).greyscale().raw().toBuffer();

const measurements = JSON.parse(await fs.readFile(path.join(OUT, "measurements.json"), "utf8"));
const bySeverity = [...measurements.rows].sort((a, b) => a.ssim550 - b.ssim550);
const sampleRefs = new Set(
  [...bySeverity.slice(0, 20), ...bySeverity.filter((_, i) => i >= 20 && i % 17 === 0)].map(
    (row) => row.ref
  )
);

const originalOf = (ref) =>
  execFileSync("git", ["show", `HEAD:apps/web/public${ref}`], {
    cwd: REPO,
    maxBuffer: 64 * 1024 * 1024,
    encoding: "buffer",
  });

const encodedPath = (ref) =>
  path.join(PUBLIC_DIR, `${ref.slice(0, ref.length - path.extname(ref).length)}.webp`.replace(/^\//, ""));

const results = [];
for (const [index, row] of measurements.rows.entries()) {
  const inSample = sampleRefs.has(row.ref);
  const original = originalOf(row.ref);
  const encoded = await fs.readFile(encodedPath(row.ref));

  const scores = {};
  const deliveredBytes = {};
  for (const testCase of CASES) {
    if (testCase.sampleOnly && !inSample) continue;
    const [beforeDelivered, afterDelivered] = await Promise.all([
      deliver(original, testCase.device),
      deliver(encoded, testCase.device),
    ]);
    const [a, b] = await Promise.all([
      lumaOf(beforeDelivered, testCase.device),
      lumaOf(afterDelivered, testCase.device),
    ]);
    scores[testCase.key] = ssim(a, b, testCase.device);
    deliveredBytes[testCase.key] = { before: beforeDelivered.length, after: afterDelivered.length };
  }

  results.push({ ref: row.ref, format: row.format, inSample, scores, deliveredBytes });
  if ((index + 1) % 100 === 0) process.stdout.write(`  ${index + 1}/${measurements.rows.length}\n`);
}

await fs.writeFile(path.join(OUT, "delivered.json"), JSON.stringify({ cases: CASES, results }));

const quantile = (values, p) => {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(p * (sorted.length - 1))];
};
for (const testCase of CASES) {
  const scores = results.map((r) => r.scores[testCase.key]).filter((s) => s !== undefined);
  const bytes = results
    .map((r) => r.deliveredBytes[testCase.key])
    .filter(Boolean)
    .reduce((acc, b) => ({ before: acc.before + b.before, after: acc.after + b.after }), { before: 0, after: 0 });
  console.log(
    `${testCase.key.padEnd(9)} n=${String(scores.length).padStart(3)}  ` +
      `min ${quantile(scores, 0).toFixed(4)}  p05 ${quantile(scores, 0.05).toFixed(4)}  ` +
      `median ${quantile(scores, 0.5).toFixed(4)}  max ${quantile(scores, 1).toFixed(4)}  ` +
      `mean delivered ${(bytes.before / scores.length / 1024).toFixed(0)}K -> ${(bytes.after / scores.length / 1024).toFixed(0)}K`
  );
}

/**
 * Before/after tiles of the pixels the browser paints.
 *
 * Both sides go through the same path the app uses: the Next image optimiser
 * at q75, at the width the layout asks for, never upscaled past the source.
 * The only difference between the two columns is which source went in.
 *
 * Display tiles are lossless WebP: the artefacts under review must not be
 * re-encoded on their way to the page.
 */
import { execFileSync } from "child_process";
import fs from "fs/promises";
import path from "path";
import sharp from "sharp";

const REPO = "/home/scottdensmore/Developer/scottdensmore/contoso";
const PUBLIC_DIR = path.join(REPO, "apps/web/public");
const OUT = path.dirname(new URL(import.meta.url).pathname);

const OPTIMISER_QUALITY = 75;
const RETINA_CROP = 440;

const SAMPLES = [
  { ref: "/images/products/hiking-clothing/102/main.jpg", note: "weakest score in the catalogue" },
  { ref: "/images/products/backpacks/76/detail.jpg", note: "weakest of the heavy files" },
  { ref: "/images/products/tents/26/main.jpg", note: "fine mesh and guy lines" },
  { ref: "/images/7/45e09e69-17c4-47d9-a501-2f8177e34349.png", note: "weakest of the 3 MB PNGs" },
  { ref: "/images/17/b77e9f01-195b-4870-bc86-c4f988bc71e8.png", note: "typical PNG" },
  { ref: "/images/products/hiking-footwear/149/angle.jpg", note: "typical JPEG" },
];

const dataUri = (buf) => `data:image/webp;base64,${buf.toString("base64")}`;

async function deliver(source, deviceWidth) {
  const meta = await sharp(source).metadata();
  const width = Math.min(deviceWidth, meta.width);
  return sharp(source)
    .resize(width, width, { fit: "inside", withoutEnlargement: true })
    .webp({ quality: OPTIMISER_QUALITY })
    .toBuffer();
}

/** Delivered, then painted into the box at its device size. */
async function paint(source, deviceWidth) {
  const delivered = await deliver(source, deviceWidth);
  return {
    bytes: delivered.length,
    tile: await sharp(delivered)
      .resize(deviceWidth, deviceWidth, { fit: "fill" })
      .webp({ lossless: true })
      .toBuffer(),
  };
}

/** A 1:1 slice of what a 2x screen paints in the 550px detail box. */
async function retina(source) {
  const delivered = await deliver(source, 1100);
  const scaled = await sharp(delivered).resize(1100, 1100, { fit: "fill" }).toBuffer();
  return sharp(scaled)
    .extract({
      left: Math.floor((1100 - RETINA_CROP) / 2),
      top: Math.floor((1100 - RETINA_CROP) / 2),
      width: RETINA_CROP,
      height: RETINA_CROP,
    })
    .webp({ lossless: true })
    .toBuffer();
}

const delivered = JSON.parse(await fs.readFile(path.join(OUT, "delivered.json"), "utf8"));
const scoreFor = (ref) => delivered.results.find((row) => row.ref === ref);

const encodedPath = (ref) =>
  path.join(PUBLIC_DIR, `${ref.slice(0, ref.length - path.extname(ref).length)}.webp`.replace(/^\//, ""));

const out = [];
let bytes = 0;
for (const sample of SAMPLES) {
  const original = execFileSync("git", ["show", `HEAD:apps/web/public${sample.ref}`], {
    cwd: REPO,
    maxBuffer: 64 * 1024 * 1024,
    encoding: "buffer",
  });
  const encoded = await fs.readFile(encodedPath(sample.ref));

  const tiles = {};
  const sizes = {};
  for (const [key, source] of [["before", original], ["after", encoded]]) {
    const detail = await paint(source, 550);
    const grid = await paint(source, 350);
    tiles[`${key}550`] = detail.tile;
    tiles[`${key}350`] = grid.tile;
    tiles[`${key}Retina`] = await retina(source);
    sizes[key] = { detail: detail.bytes, grid: grid.bytes };
  }
  for (const value of Object.values(tiles)) bytes += value.length;

  const score = scoreFor(sample.ref);
  out.push({
    ref: sample.ref,
    note: sample.note,
    sourceBefore: original.length,
    sourceAfter: encoded.length,
    deliveredBefore: sizes.before.detail,
    deliveredAfter: sizes.after.detail,
    detail1x: score.scores.detail1x,
    grid1x: score.scores.grid1x,
    detail2x: score.scores.detail2x,
    tiles: Object.fromEntries(Object.entries(tiles).map(([k, v]) => [k, dataUri(v)])),
  });
  console.log(sample.ref, (bytes / 1024 ** 2).toFixed(2), "MiB");
}

await fs.writeFile(path.join(OUT, "tiles.json"), JSON.stringify(out));
console.log("raw tile bytes", (bytes / 1024 ** 2).toFixed(2), "MiB");

