/** Assemble the review page from the measured data and the rendered tiles. */
import fs from "fs/promises";
import path from "path";

const OUT = path.dirname(new URL(import.meta.url).pathname);
const read = async (name) => JSON.parse(await fs.readFile(path.join(OUT, name), "utf8"));

const tiles = await read("tiles.json");
const measurements = await read("measurements.json");
const delivered = await read("delivered.json");
const alternatives = { ...(await read("alternatives.json")), ...(await read("alternatives-1100.json")) };

const rows = measurements.rows;
const png = rows.filter((r) => r.format === "png");
const jpeg = rows.filter((r) => r.format === "jpeg");
const sum = (list, key) => list.reduce((total, row) => total + row[key], 0);
const mib = (bytes) => (bytes / 1024 ** 2).toFixed(1);
const kib = (bytes) => Math.round(bytes / 1024);
const pct = (before, after) => Math.round((1 - after / before) * 100);
const mean = (values) => values.reduce((s, v) => s + v, 0) / values.length;
const quantile = (values, p) => {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(p * (sorted.length - 1))];
};

const catalogueBefore = sum(rows, "before");
const catalogueAfter = sum(rows, "after");

const caseRows = delivered.cases.map((testCase) => {
  const scores = delivered.results
    .map((row) => row.scores[testCase.key])
    .filter((score) => score !== undefined);
  const bytes = delivered.results
    .map((row) => row.deliveredBytes[testCase.key])
    .filter(Boolean);
  return {
    ...testCase,
    n: scores.length,
    min: quantile(scores, 0),
    p05: quantile(scores, 0.05),
    median: quantile(scores, 0.5),
    max: quantile(scores, 1),
    weakCount: scores.filter((s) => s < 0.94).length,
    meanBefore: mean(bytes.map((b) => b.before)),
    meanAfter: mean(bytes.map((b) => b.after)),
  };
});

// The originals are 1024px, so no setting can supply more than 1024 and the
// densities are capped there as well as at 1x.
const SOURCE_WIDTH = 1024;
const density = (maxDim, devicePx) => Math.min(Math.min(maxDim, SOURCE_WIDTH) / devicePx, 1);

const OPTIONS = [
  { label: "q75/600", note: "" },
  { label: "q82/600", note: "delivered" },
  { label: "q88/600", note: "" },
  { label: "q82/800", note: "" },
  { label: "q90/800", note: "" },
  { label: "q82/1100", note: "no downscale; matches today" },
];

const sampleQ82 = alternatives["q82/600"].bytes;
const optionRows = OPTIONS.map((option) => {
  const alt = alternatives[option.label];
  const maxDim = Number(option.label.split("/")[1]);
  return {
    ...option,
    maxDim,
    bytes: option.label === "q82/600" ? catalogueAfter : (alt.bytes / sampleQ82) * catalogueAfter,
    exact: option.label === "q82/600",
    detail2x: density(maxDim, 1100),
    grid2x: density(maxDim, 700),
    meanSsim: mean(alt.scores),
    worstMean: mean(alt.worstScores),
  };
});

const escape = (value) =>
  String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const viewport = (label, width, tile, ref, description) => `
          <div class="viewport">
            <span class="vp-label">${label}</span>
            <div class="stack" style="--w: ${width}px">
              <img class="is-before" src="${tile.before}" alt="${escape(ref)}, ${description}, from the original" width="${width}" height="${width}">
              <img class="is-after" src="${tile.after}" alt="${escape(ref)}, ${description}, from the WebP" width="${width}" height="${width}">
            </div>
          </div>`;

const plates = tiles
  .map(
    (tile, index) => `
      <figure class="plate" data-state="after">
        <figcaption class="plate-head">
          <div class="plate-id">
            <span class="eyebrow">Sample ${index + 1}</span>
            <code class="path">${escape(tile.ref)}</code>
            <p class="plate-note">${escape(tile.note)}</p>
          </div>
          <dl class="plate-stats">
            <div><dt>On disk</dt><dd>${kib(tile.sourceBefore)} &rarr; ${kib(tile.sourceAfter)} KiB</dd></div>
            <div><dt>Detail 1&times;</dt><dd>${tile.detail1x.toFixed(4)}</dd></div>
            <div><dt>Grid 1&times;</dt><dd>${tile.grid1x.toFixed(4)}</dd></div>
            <div><dt>Detail 2&times;</dt><dd class="${tile.detail2x < 0.94 ? "is-weak" : ""}">${tile.detail2x.toFixed(4)}</dd></div>
          </dl>
          <div class="switch" role="group" aria-label="Compare ${escape(tile.ref)}">
            <button type="button" data-show="before">Before</button>
            <button type="button" data-show="after" aria-pressed="true">After</button>
          </div>
        </figcaption>

        <div class="card">
${viewport("Detail page &middot; 550&thinsp;&times;&thinsp;550", 550, { before: tile.tiles.before550, after: tile.tiles.after550 }, tile.ref, "as painted at 550 pixels")}
${viewport("Home grid &middot; 350&thinsp;&times;&thinsp;350", 350, { before: tile.tiles.before350, after: tile.tiles.after350 }, tile.ref, "as painted at 350 pixels")}
${viewport("Detail page on a 2&times; screen &middot; device pixels, magnified", 440, { before: tile.tiles.beforeRetina, after: tile.tiles.afterRetina }, tile.ref, "centre crop as a 2x screen paints it")}
        </div>
      </figure>`
  )
  .join("\n");

const html = `<title>WebP re-encode: before and after at display size</title>
<style>
