    color-scheme: light dark;

    --ground: #f4f6f4;
    --raised: #ffffff;
    --ink: #16191a;
    --ink-soft: #565d58;
    --ink-faint: #7d857f;
    --rule: #dde2de;
    --accent: #2c6349;
    --accent-soft: #e4ede7;
    --flag: #7f5406;
    --flag-soft: #f8efdb;

    /* Fixed in both themes. A tinted surround biases what the eye reports, so
       every image below sits on the neutral grey a print is judged against. */
    --card: #767676;
    --card-ink: #f4f4f4;

    --sans: ui-sans-serif, system-ui, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;

    --measure: 66ch;
    --page: 1280px;
  }

  @media (prefers-color-scheme: dark) {
