/**
 * Three candidate settings, scored the way the app delivers them.
 *
 * Catalogue bytes across all 852; delivered fidelity on the 69-image sample at
 * the four places an image lands. Every image in the catalogue appears on a
 * product detail page -- the grid shows `images[0]`, the detail page shows all
 * of them -- so one setting has to serve both and there is nothing to split.
 */
import { execFileSync } from "child_process";
import fs from "fs/promises";
import path from "path";
import sharp from "sharp";

const REPO = "/home/scottdensmore/Developer/scottdensmore/contoso";
const OUT = path.dirname(new URL(import.meta.url).pathname);
const OPTIMISER_QUALITY = 75;

const CANDIDATES = [
  { label: "q82/600", quality: 82, maxDim: 600 },
  { label: "q88/800", quality: 88, maxDim: 800 },
  { label: "q90/1024", quality: 90, maxDim: 1024 },
];

const CASES = [
  { key: "detail1x", device: 550 },
  { key: "grid1x", device: 350 },
  { key: "detail2x", device: 1100 },
  { key: "grid2x", device: 700 },
];

const C1 = (0.01 * 255) ** 2;
const C2 = (0.03 * 255) ** 2;
function ssim(a, b, size) {
  const win = 8, stride = 4;
  let total = 0, n = 0;
  for (let y = 0; y + win <= size; y += stride) {
    for (let x = 0; x + win <= size; x += stride) {
      let sa = 0, sb = 0, saa = 0, sbb = 0, sab = 0;
      for (let j = 0; j < win; j += 1) {
        for (let i = 0; i < win; i += 1) {
          const idx = (y + j) * size + (x + i);
          const va = a[idx], vb = b[idx];
          sa += va; sb += vb; saa += va * va; sbb += vb * vb; sab += va * vb;
        }
      }
      const c = win * win;
      const ma = sa / c, mb = sb / c;
      const va = saa / c - ma * ma, vb = sbb / c - mb * mb;
      const cov = sab / c - ma * mb;
      total += ((2 * ma * mb + C1) * (2 * cov + C2)) / ((ma * ma + mb * mb + C1) * (va + vb + C2));
      n += 1;
    }
  }
  return total / n;
}

async function deliver(source, deviceWidth) {
  const meta = await sharp(source).metadata();
  const width = Math.min(deviceWidth, meta.width);
  return sharp(source)
    .resize(width, width, { fit: "inside", withoutEnlargement: true })
    .webp({ quality: OPTIMISER_QUALITY })
    .toBuffer();
}

const paintedLuma = async (source, deviceWidth) =>
  sharp(await deliver(source, deviceWidth))
    .resize(deviceWidth, deviceWidth, { fit: "fill" })
    .greyscale()
    .raw()
    .toBuffer();

const measurements = JSON.parse(await fs.readFile(path.join(OUT, "measurements.json"), "utf8"));
const bySeverity = [...measurements.rows].sort((a, b) => a.ssim550 - b.ssim550);
const sample = new Set(
  [...bySeverity.slice(0, 20), ...bySeverity.filter((_, i) => i >= 20 && i % 17 === 0)].map((r) => r.ref)
);

const totals = Object.fromEntries(
  CANDIDATES.map((c) => [c.label, { bytes: 0, largest: 0, scores: {} }])
);
for (const candidate of CANDIDATES) {
  for (const testCase of CASES) totals[candidate.label].scores[testCase.key] = [];
}

for (const [index, row] of measurements.rows.entries()) {
  const original = execFileSync("git", ["show", `HEAD:apps/web/public${row.ref}`], {
    cwd: REPO,
    maxBuffer: 64 * 1024 * 1024,
    encoding: "buffer",
  });
  const inSample = sample.has(row.ref);
  const reference = {};
  if (inSample) {
    for (const testCase of CASES) {
      reference[testCase.key] = await paintedLuma(original, testCase.device);
    }
  }

  for (const candidate of CANDIDATES) {
    const encoded = await sharp(original)
      .resize(candidate.maxDim, candidate.maxDim, { fit: "inside", withoutEnlargement: true })
      .webp({ quality: candidate.quality })
      .toBuffer();
    totals[candidate.label].bytes += encoded.length;
    totals[candidate.label].largest = Math.max(totals[candidate.label].largest, encoded.length);

    if (inSample) {
      for (const testCase of CASES) {
        const painted = await paintedLuma(encoded, testCase.device);
        totals[candidate.label].scores[testCase.key].push(
          ssim(reference[testCase.key], painted, testCase.device)
        );
      }
    }
  }
  if ((index + 1) % 100 === 0) process.stdout.write(`  ${index + 1}/${measurements.rows.length}\n`);
}

await fs.writeFile(path.join(OUT, "candidates.json"), JSON.stringify(totals));

const quantile = (values, p) => {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(p * (sorted.length - 1))];
};
for (const candidate of CANDIDATES) {
  const t = totals[candidate.label];
  const line = CASES.map((testCase) => {
    const scores = t.scores[testCase.key];
    return `${testCase.key} med ${quantile(scores, 0.5).toFixed(4)} min ${quantile(scores, 0).toFixed(4)}`;
  }).join("  ");
  console.log(
    `${candidate.label.padEnd(9)} ${(t.bytes / 1024 ** 2).toFixed(1).padStart(6)} MiB  ` +
      `largest ${(t.largest / 1024).toFixed(0).padStart(4)} KiB  ${line}`
  );
}

